import { filter, Observable, Subject } from 'rxjs';
import type { GameStorage, UpdateOptions } from '../lib/storage/game-storage';

/**
 * A storage for specs that answers late, as a Firebase backend would: no
 * watcher hears anything and no write lands before `flush()`. A service that
 * counts on storage answering at once fails against it.
 *
 * Provide it with `{ provide: GameStorage, useValue: new LateGameStorage() }`.
 */
export class LateGameStorage implements GameStorage {
  private readonly values = new Map<string, string>();
  private readonly changed = new Subject<string>();
  private pending: (() => void)[] = [];
  /** Per key, the ids of the changes made once that landed. */
  private readonly applied = new Map<string, Set<string>>();

  public constructor(stored: Record<string, unknown> = {}) {
    for (const [key, value] of Object.entries(stored)) {
      this.values.set(key, JSON.stringify(value));
    }
  }

  public watch(key: string): Observable<unknown> {
    return new Observable((subscriber) => {
      this.pending.push(() => subscriber.next(this.stored(key)));
      return this.changed
        .pipe(filter((changedKey) => changedKey === key))
        .subscribe(() => subscriber.next(this.stored(key)));
    });
  }

  public write(key: string, value: unknown): void {
    this.pending.push(() => this.store(key, value));
  }

  /**
   * Resolves true once `flush()` (or `flushLast()`) answered the change,
   * false when the change threw. A change made `once` lands only for an id
   * not seen under the key before, as the Firestore backend does.
   */
  public update(
    key: string,
    change: (stored: unknown) => unknown,
    { once }: UpdateOptions = {}
  ): Promise<boolean> {
    return new Promise((resolve) =>
      this.pending.push(() => {
        const applied = this.applied.get(key) ?? new Set<string>();
        if (once !== undefined && applied.has(once)) {
          resolve(true);
          return;
        }
        try {
          this.store(key, change(this.stored(key)));
          if (once !== undefined) {
            this.applied.set(key, applied.add(once));
          }
          resolve(true);
        } catch {
          // As the real backends: a change that fails is dropped.
          resolve(false);
        }
      })
    );
  }

  /** Answers everything asked so far. */
  public flush(): void {
    const pending = this.pending;
    this.pending = [];
    pending.forEach((answer) => answer());
  }

  /**
   * Answers only the latest thing asked; the rest still waits for `flush()`
   * - a change from another device that overtakes one made here.
   */
  public flushLast(): void {
    this.pending.pop()?.();
  }

  /** The value stored under a key, null when there is none. */
  public stored(key: string): unknown {
    const json = this.values.get(key);
    return json == null ? null : JSON.parse(json);
  }

  private store(key: string, value: unknown): void {
    const json = JSON.stringify(value);
    if (this.values.get(key) !== json) {
      this.values.set(key, json);
      this.changed.next(key);
    }
  }
}
